export function getFleetWallet(query) {
  if (!query) return null;
  const qStr = String(query).trim().toLowerCase();
  const qNum = parseInt(qStr, 10);
  
  if (!isNaN(qNum) && qNum >= 1 && qNum <= FLEET_STATIC_WALLETS.length) {
    return FLEET_STATIC_WALLETS[qNum - 1];
  }
  
  return FLEET_STATIC_WALLETS.find(w => 
    String(w.index) === qStr ||
    String(w.user_id) === qStr ||
    String(w.phone).replace(/[^0-9]/g, '') === qStr.replace(/[^0-9]/g, '')
  ) || null;
}

